package com.ridelink.drivervehicle.controller;
import com.ridelink.drivervehicle.dto.DriverDtos.*; import com.ridelink.drivervehicle.service.DriverService; import jakarta.validation.Valid; import java.net.URI; import java.util.List; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/drivers") public class DriverController {private final DriverService s;public DriverController(DriverService s){this.s=s;} @PostMapping("/profile") ResponseEntity<DriverResponse> create(@Valid @RequestBody ProfileRequest r){DriverResponse d=s.create(r);return ResponseEntity.created(URI.create("/api/v1/drivers/"+d.id())).body(d);}@PutMapping("/{id}/availability") DriverResponse availability(@PathVariable String id,@Valid @RequestBody AvailabilityRequest r){return s.availability(id,r);}@PutMapping("/{id}/location") DriverResponse location(@PathVariable String id,@Valid @RequestBody LocationRequest r){return s.location(id,r);}@GetMapping("/available") List<DriverResponse> available(@RequestParam String zone){return s.available(zone);} }
